{
  "name": "实验数据文件写入器",
  "name_en": "Experiment Data File Writer",
  "manufacturer": "",
  "description": "用于实验扫描过程中记录和导出数据的通用文件写入组件。它负责保存文件头、测量数据以及相关元数据，如用户名、命令、注释、开始/结束时间、设备列表、信号列表和对应数据。",
  "description_en": "A generic file-writing component used to record and export data during laboratory scan workflows. It stores headers, measurement data, and related metadata such as username, command, comments, start/end timestamps, device lists, signal lists, and associated data.",
  "tag_hints": [
    "data logging",
    "scan data export",
    "experiment metadata",
    "file writing",
    "measurement record",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭文件写入过程。",
      "description_en": "Close the file writing process."
    },
    {
      "action_name": "auto-getCommand",
      "description": "获取命令信息。",
      "description_en": "Get the command information."
    },
    {
      "action_name": "auto-getComments",
      "description": "获取注释列表。",
      "description_en": "Get the comments list."
    },
    {
      "action_name": "auto-getDataSize",
      "description": "获取数据行数。",
      "description_en": "Get the data size in number of lines."
    },
    {
      "action_name": "auto-getDevices",
      "description": "获取设备助记符列表。",
      "description_en": "Get the list of device mnemonics."
    },
    {
      "action_name": "auto-getDevicesData",
      "description": "获取设备数据映射。",
      "description_en": "Get the device data map."
    },
    {
      "action_name": "auto-getEndDate",
      "description": "获取结束时间。",
      "description_en": "Get the end timestamp."
    },
    {
      "action_name": "auto-getFileName",
      "description": "获取文件名。",
      "description_en": "Get the file name."
    },
    {
      "action_name": "auto-getSignals",
      "description": "获取信号助记符列表。",
      "description_en": "Get the list of signal mnemonics."
    },
    {
      "action_name": "auto-getSignalsData",
      "description": "获取信号数据映射。",
      "description_en": "Get the signal data map."
    },
    {
      "action_name": "auto-getStartDate",
      "description": "获取开始时间。",
      "description_en": "Get the start timestamp."
    },
    {
      "action_name": "auto-getUsername",
      "description": "获取用户名信息。",
      "description_en": "Get the username information."
    },
    {
      "action_name": "auto-insertComment",
      "description": "插入一条新注释。",
      "description_en": "Insert a new comment."
    },
    {
      "action_name": "auto-insertDevice",
      "description": "插入一个新设备助记符。",
      "description_en": "Insert a new device mnemonic."
    },
    {
      "action_name": "auto-insertDeviceData",
      "description": "为指定设备插入一条数据。",
      "description_en": "Insert a data value for the specified device."
    },
    {
      "action_name": "auto-insertSignal",
      "description": "插入一个新信号助记符。",
      "description_en": "Insert a new signal mnemonic."
    },
    {
      "action_name": "auto-insertSignalData",
      "description": "为指定信号插入一条数据。",
      "description_en": "Insert a data value for the specified signal."
    },
    {
      "action_name": "auto-setCommand",
      "description": "设置命令信息。",
      "description_en": "Set the command information."
    },
    {
      "action_name": "auto-setComments",
      "description": "设置注释列表。",
      "description_en": "Set the comments list."
    },
    {
      "action_name": "auto-setDataSize",
      "description": "设置数据行数。",
      "description_en": "Set the data size in number of lines."
    },
    {
      "action_name": "auto-setDevices",
      "description": "设置设备助记符列表。",
      "description_en": "Set the list of device mnemonics."
    },
    {
      "action_name": "auto-setDevicesData",
      "description": "设置设备数据映射。",
      "description_en": "Set the device data map."
    },
    {
      "action_name": "auto-setEndDate",
      "description": "设置结束时间。",
      "description_en": "Set the end timestamp."
    },
    {
      "action_name": "auto-setSignals",
      "description": "设置信号助记符列表。",
      "description_en": "Set the list of signal mnemonics."
    },
    {
      "action_name": "auto-setSignalsData",
      "description": "设置信号数据映射。",
      "description_en": "Set the signal data map."
    },
    {
      "action_name": "auto-setStartDate",
      "description": "设置开始时间。",
      "description_en": "Set the start timestamp."
    },
    {
      "action_name": "auto-setUsername",
      "description": "设置用户名信息。",
      "description_en": "Set the username information."
    },
    {
      "action_name": "auto-writeData",
      "description": "将测量数据写入文件。",
      "description_en": "Write measurement data to the file."
    },
    {
      "action_name": "auto-writeHeader",
      "description": "将文件头信息写入文件。",
      "description_en": "Write the file header to the file."
    }
  ]
}

